function icon(name, cls='') { return `<svg class="${cls}" viewBox="0 0 ${name==='mark'?26:24} 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.mark}</svg>`; }

const logo=()=>`<span class="logo">${icon('mark')}<span>rast<span class="dot">.</span></span></span>`;
const img=(src,alt='Stock photo representing a fictional profile',cls='')=>`<img src="${esc(src)}" alt="${esc(alt)}" class="${cls}" loading="eager" draggable="false">`;
const photo=n=>`assets/portrait-${n}.jpg`;
